source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = {r for r in range(h) if all(v == 8 for v in grid[r])}
    sep_cols = {c for c in range(w) if all(grid[r][c] == 8 for r in range(h))}
    def segments(size, separators):
        result, start = [], 0
        for i in range(size):
            if i in separators:
                if start < i:
                    result.append(range(start, i))
                start = i + 1
        if start < size:
            result.append(range(start, size))
        largest = max(map(len, result))
        return [seg for seg in result if len(seg) == largest]
    row_segments = segments(h, sep_rows)
    col_segments = segments(w, sep_cols)
    row_of = {r: i for i, seg in enumerate(row_segments) for r in seg}
    col_of = {c: i for i, seg in enumerate(col_segments) for c in seg}
    marks = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (2, 3) and r in row_of and c in col_of:
                marks.setdefault(color, set()).add((row_of[r], col_of[c]))
    strokes = {}
    for color, points in marks.items():
        for rr in {p[0] for p in points}:
            cols = [cc for r, cc in points if r == rr]
            if len(cols) >= 2:
                for cc in range(min(cols), max(cols) + 1):
                    strokes.setdefault((rr, cc), set()).add(color)
        for cc in {p[1] for p in points}:
            rows = [rr for rr, c in points if c == cc]
            if len(rows) >= 2:
                for rr in range(min(rows), max(rows) + 1):
                    strokes.setdefault((rr, cc), set()).add(color)
    out = [row[:] for row in grid]
    for (ri, ci), colors in strokes.items():
        val = 6 if len(colors) > 1 else next(iter(colors))
        for r in row_segments[ri]:
            for c in col_segments[ci]:
                out[r][c] = val
    return out
